	private static function connection_fields( $s ) {
		echo '<h2>Conexiones externas</h2><p>Configura sólo el destino que usarás. Los secretos ya guardados no se muestran; deja el campo vacío para conservarlos.</p><table class="form-table"><tr><th colspan="2"><h3>Servidor Linux por SFTP</h3></th></tr>';
