	private static function field( $key, $label, $s, $type = 'text' ) { $secret = in_array( $key, self::secret_fields(), true ); echo '<tr><th><label for="' . esc_attr( $key ) . '">' . esc_html( $label ) . '</label></th><td><input class="regular-text" type="' . esc_attr( $type ) . '" id="' . esc_attr( $key ) . '" name="digitalisimo_backups[' . esc_attr( $key ) . ']" value="' . esc_attr( $secret ? '' : $s[ $key ] ) . '"' . ( $secret && $s[ $key ] ? ' placeholder="Guardado · escribe sólo para reemplazar"' : '' ) . '></td></tr>'; }
	public static function save() {
